"""Run from app folder. Heal v2: gives the AI the real column names, self-corrects a failing example query once, never shows a query that does not run, and warns on low confidence. Backups made; idempotent."""
import shutil, sys, time
EDITS = {'agent/heal.py': [('# ----------------------------------------------------------------------------- the diagnosis\n_PROMPT = """You are the self-repair assistant for a hospital-data AI agent that answers questions with read-only SQL.\n', '# ----------------------------------------------------------------------------- the diagnosis\n_IDENT = re.compile(r"^[A-Za-z_][A-Za-z0-9_]{0,63}$")\n\n\ndef _table_names(sqls):\n    names = []\n    for q in sqls or []:\n        for m in re.finditer(r"(?i)\\b(?:from|join)\\s+\\[?(?:dbo\\.)?\\[?([A-Za-z_][A-Za-z0-9_]*)\\]?", q or ""):\n            t = m.group(1)\n            if _IDENT.match(t) and t.lower() not in [n.lower() for n in names]:\n                names.append(t)\n    return names[:6]\n\n\ndef _columns_text(creds, sqls):\n    """Real column names of the tables the flagged SQL used, so the AI never has to guess them."""\n    out = []\n    if not creds:\n        return "not available"\n    for t in _table_names(sqls):\n        r = _run_readonly(creds, "SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = \'%s\' ORDER BY ORDINAL_POSITION" % t, limit=80)\n        if r.get("ok") and r.get("rows"):\n            out.append(t + ": " + ", ".join(x[0] for x in r["rows"]))\n        elif r.get("ok"):\n            out.append(t + ": (table not found)")\n    return "\\n".join(out)[:1800] or "not available"\n\n\n_PROMPT = """You are the self-repair assistant for a hospital-data AI agent that answers questions with read-only SQL.\n'), ('RE-RUN OF THAT SQL (read-only): {rerun}\nANSWER PREVIEW: {preview}\n', 'RE-RUN OF THAT SQL (read-only): {rerun}\nACTUAL COLUMNS OF THE TABLES USED (taken from the database; use ONLY these names, never invent one):\n{columns}\nANSWER PREVIEW: {preview}\n'), ('        note=_mask(row.get("vote_note") or "none", 300), sql="\\n".join(_mask(q, 700) for q in sqls) or "none logged",\n        rerun=rerun, preview=_mask(row.get("preview") or "not stored", 400))\n    try:\n', '        note=_mask(row.get("vote_note") or "none", 300), sql="\\n".join(_mask(q, 700) for q in sqls) or "none logged",\n        columns=_columns_text(creds, sqls), rerun=rerun, preview=_mask(row.get("preview") or "not stored", 400))\n    try:\n'), ('            else:\n                conf = min(conf, 30)\n                why.append("example SQL failed when tested: " + str(test.get("error"))[:120])\n    if not rule:\n', '            else:\n                first_err = str(test.get("error"))[:200]\n                fixed = False\n                try:   # one self-correction pass using the real error + real columns\n                    raw2 = (llm or _ask_llm)(client, prompt + "\\n\\nYOUR EXAMPLE SQL FAILED:\\n" + example +\n                                              "\\nERROR: " + first_err + "\\nFix it using ONLY the actual column names listed above, "\n                                              "or return an empty example_sql if unsure. Same JSON format.")\n                    d2 = _extract_json(raw2) or {}\n                    ex2 = (d2.get("example_sql") or "").strip()\n                    if ex2 and safe_select(ex2):\n                        t2 = _run_readonly(creds, ex2)\n                        if t2.get("ok"):\n                            d, example, test, fixed = d2, ex2, t2, True\n                            rule = clean_rule(d2.get("rule")) or rule\n                            conf = max(0, min(100, int(d2.get("confidence") or 0))) if str(d2.get("confidence", "")).strip().isdigit() else conf\n                            conf = min(100, conf + 10) if t2["n"] else min(conf, 55)\n                            why.append("first example failed (%s); corrected using the real columns and it ran OK" % first_err[:70])\n                except Exception:\n                    pass\n                if not fixed:\n                    example = ""          # never show a query that does not run\n                    conf = min(conf, 30)\n                    why.append("example SQL failed when tested and could not be corrected: " + first_err[:120])\n    if not rule:\n')], 'guardian_console.html': [("const send=async(action)=>{await run(async()=>{const r=await request('/heal/'+p.id+'/'+action,{method:'POST',body:JSON.stringify({scope:sel.value,note:note.value,rule_text:action==='approve'?ta.value:null})});if(r.status!=='success')throw Error(r.message||'Failed');healLoad();healOpen(p.id)},'healNotice')};\nif(p.status==='pending'){const ok=make('button','btn primary','Approve & go live');ok.onclick=()=>{if(sel.value==='global'&&!confirm('This applies to EVERY client. Continue?'))return;send('approve')};const no=make('button','btn','Reject');no.onclick=()=>send('reject');act.append(sel,note,ok,no)}else if(p.status==='approved'){const rv=make('button','btn','↩ Revert (remove from AI prompt now)');rv.onclick=()=>send('revert');act.append(note,rv,make('span','','Live for: '+(p.scope==='global'?'ALL clients':p.client)))}det.appendChild(act);\ndet.appendChild(healSection('Audit trail'));const au=healBox();au.textContent=(p.events||[]).map(e=>e.ts+'  '+e.actor+'  '+e.action+'  '+(e.detail||'')).join('\\n')||'—';det.appendChild(au);det.scrollIntoView({behavior:'smooth',block:'start'})}catch(e){det.replaceChildren(make('p','',e.message))}}\n", "const send=async(action)=>{await run(async()=>{const r=await request('/heal/'+p.id+'/'+action,{method:'POST',body:JSON.stringify({scope:sel.value,note:note.value,rule_text:action==='approve'?ta.value:null})});if(r.status!=='success')throw Error(r.message||'Failed');healLoad();healOpen(p.id)},'healNotice')};\nif(p.status==='pending'){const low=p.confidence<50;if(low){const w=make('div','','⚠ Low confidence ('+p.confidence+'%). Check the diagnosis and the After preview carefully before approving.');w.style.cssText='background:#fdf1e0;border:1px solid #e7c58f;color:#8a5a14;border-radius:10px;padding:10px 12px;margin-top:14px;font-weight:700;font-size:13px';det.appendChild(w)}const ok=make('button','btn primary',low?'Approve anyway':'Approve & go live');ok.onclick=()=>{if(sel.value==='global'&&!confirm('This applies to EVERY client. Continue?'))return;if(low&&!confirm('Confidence is low. Approve anyway?'))return;send('approve')};const no=make('button','btn','Reject');no.onclick=()=>send('reject');act.append(sel,note,ok,no)}else if(p.status==='approved'){const rv=make('button','btn','↩ Revert (remove from AI prompt now)');rv.onclick=()=>send('revert');act.append(note,rv,make('span','','Live for: '+(p.scope==='global'?'ALL clients':p.client)))}det.appendChild(act);\ndet.appendChild(healSection('Audit trail'));const au=healBox();au.textContent=(p.events||[]).map(e=>e.ts+'  '+e.actor+'  '+e.action+'  '+(e.detail||'')).join('\\n')||'—';det.appendChild(au);det.scrollIntoView({behavior:'smooth',block:'start'})}catch(e){det.replaceChildren(make('p','',e.message))}}\n")]}
done = {}
for path, pairs in EDITS.items():
    s = open(path, encoding="utf-8").read()
    if path == "agent/heal.py" and "_columns_text" in s: print("ALREADY APPLIED:", path); continue
    if path == "guardian_console.html" and "Approve anyway" in s: print("ALREADY APPLIED:", path); continue
    for i, (a, b) in enumerate(pairs, 1):
        if s.count(a) != 1: print(f"{path}: anchor {i} found {s.count(a)}x. Nothing changed."); sys.exit(1)
        s = s.replace(a, b)
    done[path] = s
st = time.strftime("%Y%m%d-%H%M%S")
for p, s in done.items():
    shutil.copy2(p, p + ".bak-" + st); open(p, "w", encoding="utf-8").write(s)
print("APPLIED:", ", ".join(done) or "nothing new")
